def prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def tau_n_to_12(n):
    if n == 1:
        # n = 1, n^12 = 1. tau(1) = 1.
        return 1

    factors = prime_factorization(n)

    tau = 1
    for prime, exponent in factors.items():
        # Exponent of n^12 is 12 * exponent
        # The factor contribution is (12 * exponent + 1)
        tau *= (12 * exponent + 1)
    return tau

results = {}
for n in range(1, 31):
    tau_val = tau_n_to_12(n)
    matches = n == tau_val
    results[n] = (tau_val, matches)

print("--- Results for n=1 to 30 ---")
print("n | tau(n^12) | n = tau(n^12)?")
print("-" * 40)
for n, (tau_val, matches) in results.items():
    print(f"{n:2} | {tau_val:9} | {matches}")

